/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=product, operation=update
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Update an activity */
export type PipedriveV2ProductUpdateParams = {
  resource: 'product';
  operation: 'update';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the product to update
 * @default 0
 */
    productId?: number | Expression<number>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** The product code
     */
    code?: string | Expression<string> | PlaceholderValue;
    /** The name of the product
     */
    name?: string | Expression<string> | PlaceholderValue;
    /** ID of the user who will be marked as the owner of this product
     * @default 0
     */
    owner_id?: number | Expression<number>;
    /** Prices
     * @default {}
     */
    prices?: {
        /** Price
     */
    pricesValues?: Array<{
      /** The price of the product
       * @default 0
       */
      price?: number | Expression<number>;
      /** The currency of the price (3-letter code, e.g. USD, EUR)
       * @default USD
       */
      currency?: string | Expression<string> | PlaceholderValue;
      /** The cost of the product
       * @default 0
       */
      cost?: number | Expression<number>;
    }>;
  };
    /** The tax percentage
     * @default 0
     */
    tax?: number | Expression<number>;
    /** The unit in which this product is sold
     */
    unit?: string | Expression<string> | PlaceholderValue;
    /** Visibility of the item. If omitted, visibility will be set to the default visibility setting of this item type for the authorized user.
     * @default 3
     */
    visible_to?: '1' | '3' | Expression<string>;
    /** Custom Fields
     * @default {}
     */
    customFields?: {
        /** Property
     */
    property?: Array<{
      /** The name or key of the custom field as it appears in Pipedrive
       */
      name?: string | Expression<string> | PlaceholderValue;
      /** The value to set for the custom field
       */
      value?: string | Expression<string> | PlaceholderValue;
    }>;
  };
  };
/**
 * Whether to provide raw Pipedrive field keys and option IDs instead of human-readable names
 * @default false
 */
    rawCustomFieldKeys?: boolean | Expression<boolean>;
};

export type PipedriveV2ProductUpdateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2ProductUpdateParams>;
};